1	/**
2	 * Intent Layer (IL) — Dialogue Meaning Extraction
3	 *
4	 * Extracts structured meaning from player speech to NPC.
5	 * IL is the inverse of chatStream:
6	 *   chatStream: structured NPC state → LLM → natural text FOR player
7	 *   IL: natural player text → LLM → structured meaning FOR engine
8	 *
9	 * Output (DialogueMeaning) feeds into engine primitives:
10	 *   claims → addBelief (same as NPC beliefTransfer)
11	 *   questions → gather NPC beliefs for response context
12	 *   requestedAction → evaluate affordance, create NPC goal
13	 *   emotionalPressure → mood + relationship + event store
14	 */
15	
16	// llmSemaphore более не используется — classify внутри façade сам управляет семафором
17	import type { Agent } from './agent';
18	import type { IEventStore } from './event-types';
19	import { getEventLabel, getEventLabelSafe, BELIEF_SOURCE, isTransferable, getAffordanceIdsForVerb, getRegisteredPressureTypes, getPressureHandler, getRegisteredSpeechActs, isValidSpeechAct, isBenignSpeechAct, isTradeSpeechAct, isAccusationSpeechAct, getRegisteredClaimSources, getILTradeVerbs, getRegisteredQuestionTopics, getDefaultSpeechAct } from './event-registry';
20	import type { PressureHandlerContext } from './event-registry';
21	import type { ILConfig } from './world-types';
22	import type { PlayerJournal, CaseSummary } from './journal';
23	import { DEFAULT_IL_CONFIG } from './world-types';
24	import { classify } from './llm-client';
25	import type { LlmJsonSchema } from './llm-client';
26	
27	// Question topics registered dynamically via registerQuestionTopics() — no hardcoded array.
28	
29	/**
30	 * Build IL extraction schema dynamically with enum constraints from context.
31	 * Pattern: identical to getVolitionSchema() — constrained decoding forces valid output.
32	 * Not cached: ctx is per-call (NPC can die → knownEventTypes/locations change).
33	 */
34	// IL trade verbs registered dynamically via registerILTradeVerbs() — no hardcoded array
35	
36	function buildILSchema(ctx: ILContext): LlmJsonSchema {
37	  // All enums sorted alphabetically — eliminates positional bias in constrained decoding (9B quirk)
38	  const speechActs = getRegisteredSpeechActs().sort();
39	  const claimSources = Array.from(getRegisteredClaimSources()).sort();
40	  const pressureTypes = Array.from(getRegisteredPressureTypes()).sort();
41	  const actionVerbs = [...new Set([...getILTradeVerbs(), ...ctx.availableActions])].sort();
42	
43	  return {
44	    name: 'dialogue_meaning',
45	    strict: true,
46	    schema: {
47	      type: 'object',
48	      properties: {
49	        speechAct: { type: 'string', enum: speechActs },
50	        claims: { type: 'array', items: { type: 'object', properties: {
51	          eventType: { type: 'string', enum: ctx.knownEventTypes },
52	          subject: { type: 'string' },     // free text — resolveNpcName handles fuzzy match
53	          object: { type: 'string' },       // free text
54	          location: { type: 'string', enum: ctx.locationNames }, // display names; post-process → slug
55	          source: { type: 'string', enum: claimSources },
56	          confidence: { type: 'number' },
57	        }, required: ['confidence'], additionalProperties: false } },
58	        questions: { type: 'array', items: { type: 'object', properties: {
59	          about: { type: 'string' },        // free text — fuzzy match
60	          topic: { type: 'string', enum: getRegisteredQuestionTopics().sort() },
61	        }, required: ['about'], additionalProperties: false } },
62	        requestedAction: { type: 'object', properties: {
63	          action: { type: 'string', enum: actionVerbs },
64	          target: { type: 'string' },       // free text
65	          urgency: { type: 'number' },
66	        }, required: ['action', 'urgency'], additionalProperties: false },
67	        emotionalPressure: { type: 'object', properties: {
68	          type: { type: 'string', enum: pressureTypes },
69	          intensity: { type: 'number' },
70	        }, required: ['type', 'intensity'], additionalProperties: false },
71	        tradeIntent: { type: 'object', properties: {
72	          category: { type: 'string' },
73	          itemName: { type: 'string' },
74	        }, additionalProperties: false },
75	        extractionConfidence: { type: 'number' },
76	      },
77	      required: ['speechAct', 'extractionConfidence'],
78	      additionalProperties: false,
79	    },
80	  };
81	}
82	
83	// ─── Accusation Response Registry (modules fill) ───
84	
85	export interface AccusationResponse {
86	  goalType?: string;
87	  affordanceId?: string;
88	  trustDelta?: number;
89	  rejectReason?: string;
90	}
91	
92	/** Module registers how authority NPCs respond to accusations based on evidence quality + capabilities */
93	const ACCUSATION_RESPONSE_HANDLERS: Array<(
94	  quality: string, npc: Agent, suspectId: string
95	) => AccusationResponse | null> = [];
96	
97	export function registerAccusationResponseHandler(
98	  handler: (quality: string, npc: Agent, suspectId: string) => AccusationResponse | null,
99	): void {
100	  ACCUSATION_RESPONSE_HANDLERS.push(handler);
101	}
102	
103	export function getAccusationResponse(quality: string, npc: Agent, suspectId: string): AccusationResponse | null {
104	  for (const handler of ACCUSATION_RESPONSE_HANDLERS) {
105	    const result = handler(quality, npc, suspectId);
106	    if (result) return result;
107	  }
108	  return null;
109	}
110	
111	// ─── IL Output Types ───
112	
113	/** Speech act type — registered dynamically via registerSpeechActs(), not a union */
114	export type SpeechAct = string;  // casual conversation
115	
116	export interface Claim {
117	  /** Event type from registry (e.g. NPC_KILLED, GOODS_STOLEN) — null if no specific event */
118	  eventType?: string;
119	  /** WHO did it / is involved (NPC name as extracted) */
120	  subject?: string;
121	  /** WHO was affected / victim (NPC name) */
122	  object?: string;
123	  /** WHERE (location name) */
124	  location?: string;
125	  /** How player knows this — registered dynamically via registerClaimSources() */
126	  source: string;
127	  /** How certain the claim is (0-1) */
128	  confidence: number;
129	}
130	
131	export interface Question {
132	  /** NPC name or topic being asked about */
133	  about: string;
134	  /** Specific topic: whereabouts, opinion, knowledge, relationship, secret */
135	  topic?: string;
136	}
137	
138	export interface RequestedAction {
139	  /** Affordance-like action: investigate, arrest, examine, report */
140	  action: string;
141	  /** Target NPC name or location name */
142	  target?: string;
143	  /** How urgently player is asking (0-1) */
144	  urgency: number;
145	}
146	
147	export interface EmotionalPressure {
148	  type: 'threat' | 'bribe' | 'flattery' | 'guilt' | 'intimidation';
149	  intensity: number; // 0-1
150	}
151	
152	export interface TradeIntent {
153	  /** What category: weapon, armor, potion, food, general */
154	  category?: string;
155	  /** Specific item name if mentioned */
156	  itemName?: string;
157	}
158	
159	export interface DialogueMeaning {
160	  speechAct: SpeechAct;
161	  claims?: Claim[];
162	  questions?: Question[];
163	  requestedAction?: RequestedAction;
164	  emotionalPressure?: EmotionalPressure;
165	  tradeIntent?: TradeIntent;
166	  /** LLM self-assessed confidence in the extraction (0-1) */
167	  extractionConfidence: number;
168	  /** Internal: reason for fallback extraction (empty_response, extraction_error) */
169	  _fallback?: string;
170	}
171	
172	// ─── IL Context (what IL needs to resolve entities) ───
173	
174	export interface ILContext {
175	  /** All known NPC names with roles for prompt, e.g. "Garrett (guard)" */
176	  npcNames: string[];
177	  /** All known location display names for prompt */
178	  locationNames: string[];
179	  /** Display name → slug mapping for location resolution */
180	  locationNameToSlug: Map<string, string>;
181	  /** Known event type categories (for claim matching) */
182	  knownEventTypes: string[];
183	  /** Available action verbs NPC can perform (from ACTION_VERB_MAP) */
184	  availableActions: string[];
185	  /** NPC being talked to — display name (for prompt) */
186	  targetNpcName: string;
187	  /** NPC being talked to — agent id (для ClaudeCodeProvider per-NPC папки) */
188	  targetNpcId?: string;
189	}
190	
191	// ─── Extraction ───
192	
193	/**
194	 * Extract structured meaning from player speech using LLM.
195	 * Inverse of chatStream: natural text → structured data for the engine.
196	 */
197	export async function extractDialogueMeaning(
198	  playerMessage: string,
199	  ctx: ILContext,
200	): Promise<DialogueMeaning> {
201	  const prompt = [
202	    `Extract structured meaning from what the player said to ${ctx.targetNpcName}.`,
203	    ``,
204	    `Player said: "${playerMessage}"`,
205	    ``,
206	    `Known NPCs: ${ctx.npcNames.join(', ')}`, // names include roles e.g. "Garrett (guard)"
207	    `Known locations: ${ctx.locationNames.join(', ')}`,
208	    `Known event types: ${ctx.knownEventTypes.join(', ')}`,
209	    ``,
210	    `Extract ALL of the following that apply:`,
211	    ``,
212	    `1. speechAct: one of: ${getRegisteredSpeechActs().join(', ')}`,
213	    `   IMPORTANT: "trade" = player wants to buy, sell, browse goods, or ask about prices. Use speechAct "trade" + tradeIntent, NOT requestedAction.`,
214	    ``,
215	    `2. claims: array of factual claims the player is making (if any). Each claim:`,
216	    `   - eventType: event type if claiming something happened (use known event types, or null)`,
217	    `   - subject: WHO did it (must be a known NPC name, or null)`,
218	    `   - object: WHO was affected (NPC name, or null)`,
219	    `   - location: WHERE (must be a known location, or null)`,
220	    `   - source: how the player knows (${Array.from(getRegisteredClaimSources()).join(', ')})`,
221	    `   - confidence: 0-1 how certain the claim sounds`,
222	    ``,
223	    `3. questions: array of questions being asked (if any). Each:`,
224	    `   - about: who/what is being asked about (NPC name or topic)`,
225	    `   - topic: ${getRegisteredQuestionTopics().sort().join(', ')} (or null)`,
226	    ``,
227	    `4. requestedAction: if player is asking the NPC to DO a specific action (NOT buying/selling — that is trade):`,
228	    `   - action: use one of these verbs: ${[...getILTradeVerbs(), ...ctx.availableActions].join(', ')}`,
229	    `   - target: target NPC or location (or null)`,
230	    `   - urgency: 0-1`,
231	    ``,
232	    `5. emotionalPressure: if player is pressuring the NPC:`,
233	    `   - type: ${Array.from(getRegisteredPressureTypes()).join(', ')}`,
234	    `   - intensity: 0-1`,
235	    ``,
236	    `6. tradeIntent: if player wants to buy/sell:`,
237	    `   - category: weapon, armor, potion, food, general (or null)`,
238	    `   - itemName: specific item mentioned (or null)`,
239	    ``,
240	    `7. extractionConfidence: 0-1 your overall confidence in this extraction`,
241	    ``,
242	    `Respond ONLY with valid JSON. Omit fields that don't apply (don't include empty arrays).`,
243	  ].join('\n');
244	
245	  // classify сам управляет семафором + retry + null-on-error.
246	  const schema = buildILSchema(ctx);
247	  const raw = await classify<Record<string, unknown>>('il', {
248	    system: 'You are a dialogue meaning extractor. Extract structured information from player speech.',
249	    user: prompt,
250	    schema: { name: schema.name ?? 'il_extraction', schema: schema.schema },
251	    agentContext: ctx.targetNpcId ? { id: ctx.targetNpcId } : undefined,
252	  });
253	
254	  if (!raw) {
255	    console.warn(`  [IL] LLM returned null — falling back to ${getDefaultSpeechAct()}`);
256	    return { speechAct: getDefaultSpeechAct(), extractionConfidence: 0, _fallback: 'empty_response' };
257	  }
258	
259	  try {
260	    console.log(`  [IL] Raw LLM output: ${JSON.stringify(raw)}`);
261	    return validateAndResolve(raw, ctx);
262	  } catch (err) {
263	    console.error(`  [IL] Validation failed:`, err);
264	    return { speechAct: getDefaultSpeechAct(), extractionConfidence: 0, _fallback: 'extraction_error' };
265	  }
266	}
267	
268	// ─── Validation & Entity Resolution ───
269	
270	// Speech acts, claim sources, pressure types — all registered dynamically via registries
271	
272	function validateAndResolve(raw: Record<string, unknown>, ctx: ILContext): DialogueMeaning {
273	  if (!isValidSpeechAct(raw.speechAct as string)) {
274	    console.warn(`  [IL] Invalid speechAct '${raw.speechAct}' — falling back to '${getDefaultSpeechAct()}'`);
275	  }
276	  if (raw.extractionConfidence == null || isNaN(Number(raw.extractionConfidence))) {
277	    console.warn(`  [IL] Missing/invalid extractionConfidence '${raw.extractionConfidence}' — defaulting to 0.5`);
278	  }
279	
280	  // Semantic correction: tradeIntent presence overrides speechAct to trade.
281	  // Root cause: constrained decoding forces requestedAction.action into affordance verbs,
282	  // so "show me your wares" → model picks 'steal' (nearest verb). With enums, we need
283	  // explicit signal priority: tradeIntent > requestedAction when both present.
284	  let speechAct: SpeechAct = isValidSpeechAct(raw.speechAct as string)
285	    ? raw.speechAct as string
286	    : getDefaultSpeechAct();
287	  // Detect trade intent from multiple signals — IL trade verbs registered dynamically.
288	  const tradeIntentObj = raw.tradeIntent && typeof raw.tradeIntent === 'object' ? raw.tradeIntent as Record<string, unknown> : null;
289	  const hasTradeContent = tradeIntentObj && (tradeIntentObj.category || tradeIntentObj.itemName);
290	  const raObj = raw.requestedAction && typeof raw.requestedAction === 'object' ? raw.requestedAction as Record<string, unknown> : null;
291	  const actionIsTrade = raObj && getILTradeVerbs().has(String(raObj.action));
292	
293	  if ((hasTradeContent || actionIsTrade) && !isTradeSpeechAct(speechAct)) {
294	    console.warn(`  [IL] Trade signals detected (tradeIntent: ${!!hasTradeContent}, action: ${raObj?.action}) but speechAct='${speechAct}' — correcting to trade`);
295	    // Find the first registered trade speech act
296	    const tradeAct = getRegisteredSpeechActs().find(a => isTradeSpeechAct(a));
297	    if (tradeAct) speechAct = tradeAct;
298	  }
299	
300	  // When trade detected, requestedAction and emotionalPressure are noise
301	  const isTradeCtx = isTradeSpeechAct(speechAct);
302	  if (isTradeCtx && raw.requestedAction) console.warn(`  [IL] Discarding requestedAction (trade context)`);
303	  if (isTradeCtx && raw.emotionalPressure) console.warn(`  [IL] Discarding emotionalPressure (trade context)`);
304	
305	  const result: DialogueMeaning = {
306	    speechAct,
307	    extractionConfidence: clamp(Number(raw.extractionConfidence) || 0.5),
308	  };
309	
310	  // Resolve claims
311	  if (Array.isArray(raw.claims) && raw.claims.length > 0) {
312	    result.claims = raw.claims
313	      .map((c: Record<string, unknown>) => resolveClaim(c, ctx))
314	      .filter(Boolean) as Claim[];
315	    if (result.claims.length === 0) delete result.claims;
316	  }
317	
318	  // Resolve questions
319	  if (Array.isArray(raw.questions) && raw.questions.length > 0) {
320	    result.questions = raw.questions
321	      .map((q: Record<string, unknown>) => ({
322	        about: resolveNpcName(String(q.about ?? ''), ctx.npcNames) ?? String(q.about ?? ''),
323	        topic: q.topic ? String(q.topic) : undefined,
324	      }))
325	      .filter((q) => q.about);
326	    if (result.questions.length === 0) delete result.questions;
327	  }
328	
329	  // Resolve requested action (skip if trade — enum-forced hallucination)
330	  if (!isTradeCtx && raw.requestedAction && typeof raw.requestedAction === 'object') {
331	    const ra = raw.requestedAction as Record<string, unknown>;
332	    if (ra.action) {
333	      let resolvedTarget: string | undefined;
334	      if (ra.target) {
335	        const targetStr = String(ra.target);
336	        resolvedTarget = resolveNpcName(targetStr, ctx.npcNames) ?? resolveLocation(targetStr, ctx.locationNames);
337	        if (!resolvedTarget) {
338	          console.warn(`  [IL] requestedAction target '${targetStr}' not resolved to known NPC or location — using raw`);
339	          resolvedTarget = targetStr;
340	        }
341	      }
342	      result.requestedAction = {
343	        action: String(ra.action).toLowerCase(),
344	        target: resolvedTarget,
345	        urgency: clamp(Number(ra.urgency) || 0.5),
346	      };
347	    }
348	  }
349	
350	  // Resolve emotional pressure
351	  // Skip if trade (hallucinated). For benign speechActs, require high intensity (>0.5) —
352	  // 9B model hallucinates low-intensity threat/intimidation on innocent phrases.
353	  if (!isTradeCtx && raw.emotionalPressure && typeof raw.emotionalPressure === 'object') {
354	    const ep = raw.emotionalPressure as Record<string, unknown>;
355	    const epIntensity = clamp(Number(ep.intensity) || 0.5);
356	    if (getRegisteredPressureTypes().has(String(ep.type))) {
357	      if (isBenignSpeechAct(speechAct) && epIntensity <= 0.5) {
358	        console.warn(`  [IL] Discarding low-intensity pressure '${ep.type}' (${epIntensity}) on benign speechAct '${speechAct}' — likely hallucination`);
359	      } else {
360	        result.emotionalPressure = {
361	          type: String(ep.type) as EmotionalPressure['type'],
362	          intensity: epIntensity,
363	        };
364	      }
365	    } else if (ep.type) {
366	      console.warn(`  [IL] Invalid emotionalPressure type '${ep.type}' — dropped`);
367	    }
368	  }
369	
370	  // Resolve trade intent
371	  if (raw.tradeIntent && typeof raw.tradeIntent === 'object') {
372	    const ti = raw.tradeIntent as Record<string, unknown>;
373	    result.tradeIntent = {
374	      category: ti.category ? String(ti.category) : undefined,
375	      itemName: ti.itemName ? String(ti.itemName) : undefined,
376	    };
377	  }
378	
379	  return result;
380	}
381	
382	function resolveClaim(raw: Record<string, unknown>, ctx: ILContext): Claim | null {
383	  const rawSource = String(raw.source ?? '');
384	  if (rawSource && !getRegisteredClaimSources().has(rawSource)) {
385	    console.warn(`  [IL] Unknown claim source '${rawSource}' — keeping raw value`);
386	  }
387	  const source = rawSource;
388	  const subject = raw.subject ? resolveNpcName(String(raw.subject), ctx.npcNames) : undefined;
389	  if (raw.subject && !subject) console.warn(`  [IL] Could not resolve claim subject '${raw.subject}' to known NPC`);
390	  const object = raw.object ? resolveNpcName(String(raw.object), ctx.npcNames) : undefined;
391	  if (raw.object && !object) console.warn(`  [IL] Could not resolve claim object '${raw.object}' to known NPC`);
392	  const displayLoc = raw.location ? resolveLocation(String(raw.location), ctx.locationNames) : undefined;
393	  if (raw.location && !displayLoc) console.warn(`  [IL] Could not resolve claim location '${raw.location}' to known location`);
394	  // Convert display name → slug for engine consistency (principle 42)
395	  const location = displayLoc ? (ctx.locationNameToSlug.get(displayLoc) ?? undefined) : undefined;
396	  if (displayLoc && !location) console.warn(`  [IL] Location '${displayLoc}' resolved but no slug mapping found`);
397	
398	  // Must have at least some content
399	  if (!subject && !object && !raw.eventType && !location) return null;
400	
401	  return {
402	    eventType: raw.eventType ? String(raw.eventType) : undefined,
403	    subject,
404	    object,
405	    location,
406	    source,
407	    confidence: clamp(Number(raw.confidence) || 0.5),
408	  };
409	}
