411	/** Strip "(role)" suffix: "Garrett (guard)" → "garrett" */
412	function stripRole(s: string): string {
413	  return s.replace(/\s*\(.*?\)\s*$/, '').toLowerCase();
414	}
415	
416	/** Fuzzy match NPC name — case-insensitive, strips role suffix, pre-stripped for efficiency */
417	function resolveNpcName(input: string, known: string[]): string | undefined {
418	  if (!input) return undefined;
419	  const stripped = stripRole(input);
420	  const knownStripped = known.map(n => ({ orig: n, clean: stripRole(n) }));
421	  // Exact match (ignoring role suffix)
422	  const exact = knownStripped.find(k => k.clean === stripped);
423	  if (exact) return exact.orig;
424	  // Partial match (input contains known name or vice versa)
425	  const partial = knownStripped.find(k => stripped.includes(k.clean) || k.clean.includes(stripped));
426	  return partial?.orig ?? undefined;
427	}
428	
429	/** Fuzzy match location name */
430	function resolveLocation(input: string, known: string[]): string | undefined {
431	  if (!input) return undefined;
432	  const lower = input.toLowerCase();
433	  const exact = known.find((n) => n.toLowerCase() === lower);
434	  if (exact) return exact;
435	  const partial = known.find((n) => lower.includes(n.toLowerCase()) || n.toLowerCase().includes(lower));
436	  return partial ?? undefined;
437	}
438	
439	function clamp(n: number, min = 0, max = 1): number {
440	  return Math.max(min, Math.min(max, n));
441	}
