510	/**
511	 * Process evidence entries attached to a chat message.
512	 * Creates beliefs with source EVIDENCE — physical evidence is NOT trust-scaled.
513	 * Returns prompt context string describing the presented evidence.
514	 */
515	export function processEvidencePresentation(ctx: ILEffectContext): string {
516	  const evidence = ctx.presentedEvidence;
517	  if (!evidence || evidence.length === 0) return '';
518	
519	  const npc = ctx.targetAgent;
520	  const playerId = ctx.playerAgent.profile.id;
521	  const playerTrust = npc.state.relationships?.getRelationship(playerId)?.trust ?? 0;
522	  const lines: string[] = [];
523	
524	  for (const ev of evidence) {
525	    if (!ev.eventType) continue;
526	
527	    // Evidence confidence from weight field — no category string checks in engine.
528	    // Modules set evidenceWeight at creation time: physical=0.15-0.25, witness=0.5, etc.
529	    // Entries without evidenceWeight (player observations): trust-scaled fallback.
530	    const confidence = ev.evidenceWeight != null
531	      ? ev.evidenceWeight
532	      : 0.4 * playerTrust;
533	
534	    if (confidence < 0.05) continue;
535	
536	    npc.state.beliefs?.addBelief({
537	      id: crypto.randomUUID(),
538	      eventType: ev.eventType,
539	      subject: ev.suspectId ?? null,
540	      object: null,
541	      location: null,
542	      confidence,
543	      source: BELIEF_SOURCE.EVIDENCE,
544	      sourceNpcId: playerId,
545	      gameDay: ctx.gameDay,
546	      lastUpdated: ctx.gameDay,
547	    });
548	
549	    ctx.effects.push({
550	      type: 'belief_created',
551	      eventType: ev.eventType,
552	      subject: ev.perpetratorName ?? null,
553	      confidence: +confidence.toFixed(2),
554	      trust: +playerTrust.toFixed(2),
555	    });
556	
557	    const catLabel = ev.evidenceCategory ?? 'evidence';
558	    lines.push(`- "${ev.text}" (${catLabel}${ev.perpetratorName ? `, pointing to ${ev.perpetratorName}` : ''})`);
559	    console.log(`  [IL] Evidence belief: ${ev.eventType} suspect=${ev.perpetratorName} conf=${confidence.toFixed(2)} cat=${catLabel} (NOT trust-scaled)`);
560	  }
561	
562	  if (lines.length === 0) return '';
563	
564	  return [
565	    '[EVIDENCE PRESENTED]',
566	    'The player shows you documented evidence:',
567	    ...lines,
568	    'This is tangible evidence from the crime scene investigation, not just hearsay.',
569	    'Consider it alongside your own knowledge.',
570	  ].join('\n');
571	}
