575	export interface AccusationContext {
576	  suspectId: string;
577	  perpetratorName: string;
578	  crimeLabel: string;
579	  journalEvidence: CaseSummary;
580	  npcMaxConfidence: number;
581	  npcHasOwnEvidence: boolean;
582	  playerTrust: number;
583	  combinedScore: number;
584	  combinedQuality: 'strong' | 'moderate' | 'weak' | 'insufficient';
585	}
586	
587	function computeTrustBonus(trust: number): number {
588	  if (trust >= 0.7) return 1.0;
589	  if (trust >= 0.4) return 0.6;
590	  return 0.2;
591	}
