593	/**
594	 * Build accusation context for authority NPCs (investigator/canSentence).
595	 * Evidence quality is computed DETERMINISTICALLY — LLM provides voice, engine provides logic.
596	 */
597	export function buildAccusationContext(
598	  suspectId: string,
599	  claimEventType: string,
600	  npc: Agent,
601	  playerJournal: PlayerJournal,
602	  playerTrust: number,
603	  agents: Map<string, Agent>,
604	): AccusationContext {
605	  const suspectAgent = agents.get(suspectId);
606	  const perpetratorName = suspectAgent?.profile.name ?? suspectId;
607	  const crimeLabel = getEventLabelSafe(claimEventType, 'wrongdoing');
608	
609	  // Player's journal evidence
610	  const journalEvidence = playerJournal.getCaseSummary(suspectId, perpetratorName);
611	
612	  // NPC's own beliefs about suspect
613	  let npcMaxConfidence = 0;
614	  let npcHasOwnEvidence = false;
615	  if (npc.state.beliefs) {
616	    for (const b of npc.state.beliefs.getAllBeliefs()) {
617	      if (b.subject === suspectId && isTransferable(b.eventType)) {
618	        if (b.confidence > npcMaxConfidence) npcMaxConfidence = b.confidence;
619	        if (b.source !== BELIEF_SOURCE.TESTIMONY) npcHasOwnEvidence = true;
620	      }
621	    }
622	  }
623	
624	  // Combined score: journal 50% + NPC beliefs 35% + trust bonus 15%
625	  const trustBonus = computeTrustBonus(playerTrust);
626	  const combinedScore = journalEvidence.totalScore * 0.5
627	    + npcMaxConfidence * 0.35
628	    + trustBonus * 0.15;
629	
630	  const combinedQuality: AccusationContext['combinedQuality'] =
631	    combinedScore >= 0.7 ? 'strong' :
632	    combinedScore >= 0.4 ? 'moderate' :
633	    combinedScore >= 0.2 ? 'weak' :
634	    'insufficient';
635	
636	  return {
637	    suspectId, perpetratorName, crimeLabel,
638	    journalEvidence, npcMaxConfidence, npcHasOwnEvidence,
639	    playerTrust, combinedScore, combinedQuality,
640	  };
641	}
