643	/** Build NPC prompt section for formal accusation. */
644	function buildAccusationPrompt(acc: AccusationContext, npc: Agent): string {
645	  const ev = acc.journalEvidence.evidence;
646	  const evParts = Object.entries(ev).filter(([, n]) => n > 0).map(([cat, n]) => `${n} ${cat}`);
647	  const evDesc = evParts.length ? evParts.join(', ') : 'none';
648	
649	  const npcConfDesc = acc.npcMaxConfidence >= 0.6 ? 'significant suspicion'
650	    : acc.npcMaxConfidence >= 0.3 ? 'some suspicion'
651	    : acc.npcMaxConfidence > 0 ? 'faint suspicion'
652	    : 'no independent findings';
653	
654	  const trustDesc = acc.playerTrust >= 0.7 ? 'well-established'
655	    : acc.playerTrust >= 0.4 ? 'moderate'
656	    : 'low';
657	
658	  const qualityGuidance: Record<string, string> = {
659	    strong: 'This evidence warrants immediate action.',
660	    moderate: 'Worth investigating further. Tell the player what additional evidence would help.',
661	    weak: 'Not enough to act on. Explain what is missing.',
662	    insufficient: 'This accusation has no real basis. Warn the player about making unfounded accusations.',
663	  };
664	
665	  // Personality modulation
666	  let personalityNote = '';
667	  const H = npc.profile.bigFive.honesty;
668	  const C = npc.profile.bigFive.conscientiousness;
669	  if (npc.profile.investigator) {
670	    personalityNote = C >= 0.7
671	      ? 'As a disciplined investigator, you need solid evidence before acting.'
672	      : H < 0.5
673	        ? 'You might be open to... alternative forms of persuasion.'
674	        : 'You want to do the right thing but need convincing evidence.';
675	  } else if (npc.profile.canSentence) {
676	    personalityNote = 'You cannot arrest anyone. Tell the player to bring this to someone with the authority to make arrests.';
677	  }
678	
679	  return [
680	    '[FORMAL ACCUSATION]',
681	    `The player formally accuses ${acc.perpetratorName} of ${acc.crimeLabel}.`,
682	    '',
683	    'Evidence assessment:',
684	    `- Player documented evidence: ${acc.journalEvidence.quality} (${evDesc})`,
685	    `- Your own findings: ${npcConfDesc}`,
686	    `- Player trustworthiness: ${trustDesc}`,
687	    `- Combined evidence quality: ${acc.combinedQuality.toUpperCase()}`,
688	    '',
689	    qualityGuidance[acc.combinedQuality],
690	    personalityNote,
691	  ].join('\n');
692	}
