694	/**
695	 * Apply the extracted dialogue meaning to engine systems.
696	 * Returns additional context string for the NPC's chatStream response.
697	 *
698	 * Consistency contract (bilateral design):
699	 *   - Claims use isTransferable() filter, same as NPC-NPC beliefTransfer (goals.ts)
700	 *   - Confidence = claim.confidence × trust, minimum threshold 0.1
701	 *   - Relationship changes go through adjustSentiment/adjustTrust for WS broadcast
702	 *   - observe() awaited for memory consistency before NPC responds
703	 */
704	export async function applyDialogueMeaning(
705	  meaning: DialogueMeaning,
706	  ctx: ILEffectContext,
707	): Promise<string> {
708	  const npc = ctx.targetAgent;
709	  const playerId = ctx.playerAgent.profile.id;
710	  const playerName = ctx.playerAgent.profile.name;
711	  const sections: string[] = [];
712	  const cfg = ctx.ilConfig ?? DEFAULT_IL_CONFIG;
713	
714	  // 0. Evidence presentation → beliefs with source EVIDENCE (NOT trust-scaled)
715	  const evidenceContext = processEvidencePresentation(ctx);
716	  if (evidenceContext) sections.push(evidenceContext);
717	
718	  // 1. Claims → create beliefs in NPC (consistent with NPC-NPC beliefTransfer)
719	  if (meaning.claims && meaning.claims.length > 0) {
720	    const playerRel = npc.state.relationships?.getRelationship(playerId);
721	    if (!playerRel) {
722	      console.error(`  [IL] BUG: ${npc.profile.name} has no relationship to player — beliefs cannot be created`);
723	    }
724	    const playerTrust = playerRel?.trust ?? 0;
725	
726	    for (const claim of meaning.claims) {
727	      const subjectAgent = claim.subject ? findAgentByName(claim.subject, ctx.agents) : null;
728	      const objectAgent = claim.object ? findAgentByName(claim.object, ctx.agents) : null;
729	
730	      if (claim.eventType && (subjectAgent || objectAgent)) {
731	        if (!isTransferable(claim.eventType)) {
732	          ctx.effects.push({ type: 'belief_rejected', reason: 'not transferable', subject: claim.subject ?? undefined });
733	          sections.push(`${playerName} mentions something about ${claim.subject ?? 'someone'}, but it's not actionable information.`);
734	          continue;
735	        }
736	
737	        const effectiveConfidence = claim.confidence * playerTrust;
738	        if (effectiveConfidence < cfg.beliefConfidenceFloor) {
739	          ctx.effects.push({ type: 'belief_rejected', reason: 'insufficient trust', subject: claim.subject ?? undefined });
740	          sections.push(`${playerName} claims something about ${claim.subject ?? 'someone'}, but you have no reason to trust this stranger.`);
741	          continue;
742	        }
743	
744	        npc.state.beliefs?.addBelief({
745	          id: crypto.randomUUID(),
746	          eventType: claim.eventType,
747	          subject: subjectAgent?.profile.id ?? claim.subject ?? null,
748	          object: objectAgent?.profile.id ?? claim.object ?? null,
749	          location: claim.location ?? null,
750	          confidence: effectiveConfidence,
751	          source: BELIEF_SOURCE.TESTIMONY,
752	          sourceNpcId: playerId,
753	          gameDay: ctx.gameDay,
754	          lastUpdated: ctx.gameDay,
755	        });
756	
757	        ctx.effects.push({ type: 'belief_created', eventType: claim.eventType, subject: claim.subject ?? null, confidence: +effectiveConfidence.toFixed(2), trust: +playerTrust.toFixed(2) });
758	        console.log(`  [IL] Belief created in ${npc.profile.name}: ${claim.eventType} subject=${claim.subject} conf=${effectiveConfidence.toFixed(2)} (trust=${playerTrust.toFixed(2)})`);
759	        const eventLabel = getEventLabelSafe(claim.eventType);
760	        sections.push(`${playerName} claims: ${claim.subject ?? 'someone'} was involved in ${eventLabel.toLowerCase()}${claim.object ? ` against ${claim.object}` : ''}. You ${playerTrust >= cfg.trustThresholdForGoals ? 'find this somewhat credible' : 'are skeptical about this claim'}.`);
761	      } else if (claim.subject || claim.location) {
762	        const details = [claim.subject, claim.location].filter(Boolean);
763	        sections.push(`${playerName} mentions: ${details.join(', ')}. Consider this in your response.`);
764	      }
765	    }
766	  }
767	
768	  // 1b. Accusation evaluation — only for authority NPCs (investigator/canSentence)
769	  if (isAccusationSpeechAct(meaning.speechAct) && meaning.claims && meaning.claims.length > 0) {
770	    const isAuthority = npc.profile.investigator || npc.profile.canSentence;
771	    if (isAuthority && ctx.playerJournal) {
772	      const suspectClaim = meaning.claims.find((c) => c.subject);
773	      if (suspectClaim?.subject) {
774	        const suspectAgent = findAgentByName(suspectClaim.subject, ctx.agents);
775	        if (suspectAgent) {
776	          // Guards: can't accuse dead NPCs, yourself, or the authority you're talking to
777	          if (!suspectAgent.state.alive) {
778	            sections.push(`${suspectAgent.profile.name} is dead. This accusation makes no sense.`);
779	          } else if (suspectAgent.profile.isPlayer) {
780	            sections.push(`You cannot accuse yourself.`);
781	          } else if (suspectAgent.profile.id === npc.profile.id) {
782	            sections.push(`You are accusing ME? That is absurd. I am the law here.`);
783	            npc.state.relationships?.adjustSentiment(playerId, -0.2);
784	            npc.state.relationships?.adjustTrust(playerId, -0.15);
785	            ctx.effects.push({ type: 'relationship_change', field: 'sentiment', delta: -0.2 });
786	            ctx.effects.push({ type: 'relationship_change', field: 'trust', delta: -0.15 });
787	          } else {
788	          const playerTrust = npc.state.relationships?.getRelationship(playerId)?.trust ?? 0;
789	          const acc = buildAccusationContext(
790	            suspectAgent.profile.id, suspectClaim.eventType ?? '', npc,
791	            ctx.playerJournal, playerTrust, ctx.agents,
792	          );
793	
794	          // Prompt injection with structured evidence assessment
795	          sections.push(buildAccusationPrompt(acc, npc));
796	
797	          // Session-based repetition + multiple suspect tracking
798	          if (ctx.chatSession) {
799	            const session = ctx.chatSession;
800	            const suspId = suspectAgent.profile.id;
801	            const suspName = suspectAgent.profile.name;
802	            const currentHash = ctx.playerJournal.getEntriesForSuspect(suspId).length;
803	            const history = session.accusationHistory.get(suspId);
804	
805	            if (history) {
806	              if (currentHash !== history.lastJournalHash) {
807	                // New evidence found — reset
808	                history.count = 1;
809	                history.lastJournalHash = currentHash;
810	              } else {
811	                // Same evidence, repeated accusation
812	                history.count++;
813	                if (history.count === 2) {
814	                  sections.push(`The player has already accused ${suspName} of this. They haven't presented new evidence.`);
815	                } else {
816	                  sections.push(`The player keeps repeating the same accusation against ${suspName} without new evidence. This is becoming tiresome and undermining their credibility.`);
817	                }
818	                const penalty = history.count === 2 ? -0.10 : -0.12;
819	                npc.state.relationships?.adjustTrust(playerId, penalty);
820	                ctx.effects.push({ type: 'relationship_change', field: 'trust', delta: penalty });
821	              }
822	            } else {
823	              session.accusationHistory.set(suspId, { count: 1, lastJournalHash: currentHash });
824	            }
825	
826	            // Multiple suspect detection — unique suspects only
827	            const prevSuspects = session.formalAccusations.filter(a => a.suspectId !== suspId);
828	            if (prevSuspects.length > 0) {
829	              const prevNames = [...new Set(prevSuspects.map(a => a.perpetratorName))].join(', ');
830	              const uniqueCount = new Set(prevSuspects.map(a => a.suspectId)).size;
831	              if (uniqueCount === 1) {
832	                sections.push(`Note: this player previously formally accused ${prevNames}. Now they're accusing ${suspName}. Their investigative judgment may be questionable.`);
833	              } else {
834	                sections.push(`This player has now accused ${uniqueCount + 1} different people (${prevNames}, now ${suspName}). They seem to be guessing rather than investigating.`);
835	              }
836	              npc.state.relationships?.adjustTrust(playerId, -0.05);
837	              ctx.effects.push({ type: 'relationship_change', field: 'trust', delta: -0.05 });
838	            }
839	            if (!session.formalAccusations.some(a => a.suspectId === suspId)) {
840	              session.formalAccusations.push({ suspectId: suspId, perpetratorName: suspName, gameDay: ctx.gameDay });
841	            }
