1005	function findAgentByName(name: string, agents: Map<string, Agent>): Agent | undefined {
1006	  const lower = name.toLowerCase();
1007	  // Exact match first
1008	  for (const agent of agents.values()) {
1009	    if (agent.profile.name.toLowerCase() === lower) return agent;
1010	  }
1011	  // Partial match — collect all candidates, prefer shortest name (most specific)
1012	  let best: Agent | undefined;
1013	  let bestLen = Infinity;
1014	  for (const agent of agents.values()) {
1015	    const aName = agent.profile.name.toLowerCase();
1016	    if (aName.includes(lower) || lower.includes(aName)) {
1017	      if (agent.profile.name.length < bestLen) {
1018	        best = agent;
1019	        bestLen = agent.profile.name.length;
1020	      }
1021	    }
1022	  }
1023	  return best;
1024	}
