1026	/**
1027	 * Bilateral relationship adjustment via proper RelationshipGraph methods.
1028	 * Uses adjustSentiment/adjustTrust which trigger onChange → WS broadcast.
1029	 * Player side shifts by bilateralFactor (default 0.5 — player is the actor, NPC is the reactor).
1030	 */
1031	function adjustBilateral(player: Agent, npc: Agent, sentimentDelta: number, trustDelta: number, bilateralFactor = 0.5): void {
1032	  npc.state.relationships?.adjustSentiment(player.profile.id, sentimentDelta);
1033	  npc.state.relationships?.adjustTrust(player.profile.id, trustDelta);
1034	  player.state.relationships?.adjustSentiment(npc.profile.id, sentimentDelta * bilateralFactor);
1035	  player.state.relationships?.adjustTrust(npc.profile.id, trustDelta * bilateralFactor);
1036	}
