184	/** Gather evidence about a detained NPC from all agents' beliefs */
185	export class GoalManager {
186	  private goals: Map<string, NpcGoal[]> = new Map(); // ownerId → goals
187	  onGoalChange?: (data: { npcId: string; goalType: string; status: 'created' | 'completed' | 'failed'; targetName?: string }) => void;
188	
189	  /** Add a goal for an NPC */
190	  addGoal(goal: NpcGoal): void {
191	    // Contract guard: catch missing/wrong fields from module callers
192	    if (!goal.id) throw new Error(`[Goal] Missing id in goal type '${goal.type}'`);
193	    if (!goal.ownerId) throw new Error(`[Goal] Missing ownerId in goal type '${goal.type}'`);
194	    if (typeof goal.createdAtMinute !== 'number') throw new Error(`[Goal] Missing createdAtMinute in goal type '${goal.type}' for ${goal.ownerId}`);
195	    if (!goal.steps?.length) throw new Error(`[Goal] Empty steps in goal type '${goal.type}' for ${goal.ownerId}`);
196	    if (goal.waitTicks === undefined) goal.waitTicks = 0;
197	    const list = this.goals.get(goal.ownerId) ?? [];
198	    list.push(goal);
199	    // Sort by priority descending
200	    list.sort((a, b) => b.priority - a.priority);
201	    this.goals.set(goal.ownerId, list);
202	    this.onGoalChange?.({ npcId: goal.ownerId, goalType: goal.type, status: 'created', targetName: goal.data?.targetName as string });
203	  }
204	
205	  /** Get all active/pending goals for an NPC */
206	  getGoals(ownerId: string): NpcGoal[] {
207	    return (this.goals.get(ownerId) ?? []).filter(
208	      (g) => g.state === 'pending' || g.state === 'active',
209	    );
210	  }
211	
212	  /** Get the highest-priority active goal for an NPC (preempts lower-priority) */
213	  getActiveGoal(ownerId: string): NpcGoal | null {
214	    const goals = this.getGoals(ownerId);
215	    if (goals.length === 0) return null;
216	
217	    // goals[0] is the highest-priority goal (sorted desc)
218	    const top = goals[0];
219	
220	    // Preempt: if a higher-priority goal is pending while a lower one is active, switch
221	    const active = goals.find((g) => g.state === 'active');
222	    if (active && active !== top && top.state === 'pending') {
223	      active.state = 'pending'; // pause current
224	      top.state = 'active';
225	      return top;
226	    }
227	
228	    if (active) return active;
229	
230	    top.state = 'active';
231	    return top;
232	  }
233	
234	  /**
235	   * Goal watchdog. Aborts any ACTIVE goal that has made no step progress for more than
236	   * `stuckMinutes` game-minutes, freeing the NPC to re-evaluate via volition. No-progress based
237	   * (tracks currentStep advances), so legitimately long-but-progressing goals are spared — only
238	   * genuinely stuck ones (unreachable target, dead-end) are cut. Frozen owners (e.g. player chat)
239	   * reset the clock and are never aborted. Returns aborted goals; caller clears motive + logs.
240	   */
241	  sweepStuckGoals(
242	    gameMinute: number,
243	    stuckMinutes: number,
244	    skipOwner?: (ownerId: string) => boolean,
245	  ): Array<{ ownerId: string; goalType: string; goalId: string }> {
246	    if (stuckMinutes <= 0) return [];
247	    const aborted: Array<{ ownerId: string; goalType: string; goalId: string }> = [];
248	    for (const [ownerId, goals] of this.goals) {
249	      const active = goals.find((g) => g.state === 'active');
250	      if (!active) continue;
251	      // Lazy init bookkeeping on first sighting — start the clock when first seen active.
252	      if (active.lastProgressStep === undefined || active.lastProgressMinute === undefined) {
253	        active.lastProgressStep = active.currentStep;
254	        active.lastProgressMinute = gameMinute;
255	        continue;
256	      }
257	      // Frozen (player chat etc.) — don't count this time against the goal.
258	      if (skipOwner?.(ownerId)) {
259	        active.lastProgressMinute = gameMinute;
260	        continue;
261	      }
262	      // Step advanced — reset the stuck clock.
263	      if (active.currentStep > active.lastProgressStep) {
264	        active.lastProgressStep = active.currentStep;
265	        active.lastProgressMinute = gameMinute;
266	        continue;
267	      }
268	      // No progress for too long — abort the goal.
269	      if (gameMinute - active.lastProgressMinute > stuckMinutes) {
270	        active.state = 'failed';
271	        this.onGoalChange?.({ npcId: ownerId, goalType: active.type, status: 'failed' });
272	        aborted.push({ ownerId, goalType: active.type, goalId: active.id });
273	      }
274	    }
275	    return aborted;
276	  }
277	
278	  /** Check if an NPC has any active goals */
279	  hasActiveGoal(ownerId: string): boolean {
280	    return this.getActiveGoal(ownerId) !== null;
281	  }
282	
283	  /** Check if NPC has an active/pending goal with priority >= minPriority */
284	  hasActiveGoalAbove(ownerId: string, minPriority: number): boolean {
285	    const goals = this.getGoals(ownerId);
286	    return goals.some((g) => g.state !== 'completed' && g.state !== 'failed' && g.priority >= minPriority);
287	  }
