289	  /** Check if NPC is the target of someone else's goal of a specific type (e.g. arrest).
290	   *  Checks step targetId fields in active/pending goals. */
291	  isTargetOfGoalType(targetNpcId: string, goalType: string): boolean {
292	    for (const [ownerId, ownerGoals] of this.goals) {
293	      if (ownerId === targetNpcId) continue;
294	      for (const goal of ownerGoals) {
295	        if (goal.state === 'completed' || goal.state === 'failed') continue;
296	        if (goal.type !== goalType) continue;
297	        // Check if any step targets this NPC
298	        for (const step of goal.steps) {
299	          if ('targetId' in step && (step as { targetId?: string }).targetId === targetNpcId) return true;
300	        }
301	      }
302	    }
303	    return false;
304	  }
