306	  /** Complete all pending/active goals of a given type (e.g. once crime is reported, no need to keep reporting) */
307	  completeGoalsByType(type: string): number {
308	    let count = 0;
309	    for (const list of this.goals.values()) {
310	      for (const goal of list) {
311	        if (goal.type === type && (goal.state === 'pending' || goal.state === 'active')) {
312	          goal.state = 'completed';
313	          count++;
314	        }
315	      }
316	    }
317	    return count;
318	  }
