340	  /** Serializable snapshot (only active/pending goals) */
341	  toJSON(): Record<string, NpcGoal[]> {
342	    const result: Record<string, NpcGoal[]> = {};
343	    for (const [ownerId, list] of this.goals) {
344	      const active = list.filter((g) => g.state === 'pending' || g.state === 'active');
345	      if (active.length > 0) result[ownerId] = active;
346	    }
