350	  /** Restore goals from a saved snapshot — validates step actions */
351	  loadFromJSON(data: Record<string, NpcGoal[]>): void {
352	    const BUILT_IN_ACTIONS = new Set(['move_to', 'interact', 'interact_present', 'announce', 'wait']);
353	    for (const [ownerId, goals] of Object.entries(data)) {
354	      for (const goal of goals) {
355	        const invalidStep = goal.steps?.find(s => !BUILT_IN_ACTIONS.has(s.action) && !getStepHandler(s.action));
356	        if (invalidStep) {
357	          console.warn(`  [Save] Skipping goal ${goal.id} for ${ownerId} — unknown step action '${invalidStep.action}'`);
358	          continue;
359	        }
360	        this.addGoal(goal);
361	      }
362	    }
