365	  /**
366	   * Process one tick for a specific NPC's goal.
367	   * Returns the action taken, or null if no goal / goal complete.
368	   */
369	  async processGoalTick(
370	    ownerId: string,
371	    agents: Map<string, Agent>,
372	    locations: LocationGraph,
373	    runInteraction: InteractionRunner,
374	    onCrimeEvent?: (event: { type: string; subject: string; object?: string; location: string; importance: number; payload: Record<string, unknown> }) => Promise<void>,
375	    crimeScenes?: Map<string, import('./world-types').CrimeScene[]>,
376	    evidenceLayer?: EvidenceLayer,
377	    addMoodModifier?: MoodModifierCallback,
378	  ): Promise<GoalActionResult | null> {
379	    const goal = this.getActiveGoal(ownerId);
380	    if (!goal) return null;
381	
382	    const owner = agents.get(ownerId);
383	    if (!owner || !owner.state.alive) {
384	      goal.state = 'failed';
385	      if (owner) owner.state.currentMotive = undefined;
386	      this.onGoalChange?.({ npcId: ownerId, goalType: goal.type, status: 'failed' });
387	      return null;
388	    }
389	
390	    // Check if all steps are done
391	    if (goal.currentStep >= goal.steps.length) {
392	      goal.state = 'completed';
393	      this.onGoalChange?.({ npcId: ownerId, goalType: goal.type, status: 'completed' });
394	      // Clear current motive — goal fulfilled, emotional context no longer active
395	      if (owner.state.currentMotive && goal.data?.reason) {
396	        owner.state.currentMotive = undefined;
397	      }
398	      return {
399	        goalId: goal.id,
400	        goalType: goal.type,
401	        ownerId,
402	        ownerName: owner.profile.name,
403	        action: 'completed',
404	        description: `${owner.profile.name} completed goal: ${goal.type}`,
405	        goalCompleted: true,
406	        isRoutine: goal.isRoutine,
407	      };
408	    }
409	
410	    const step = goal.steps[goal.currentStep];
411	    return this.executeStep(goal, step, ownerId, owner, agents, locations, runInteraction, onCrimeEvent, crimeScenes, evidenceLayer, addMoodModifier);
412	  }
413	
414	  private async executeStep(
415	    goal: NpcGoal,
416	    step: GoalStep,
417	    ownerId: string,
418	    owner: Agent,
419	    agents: Map<string, Agent>,
420	    locations: LocationGraph,
421	    runInteraction: InteractionRunner,
422	    onCrimeEvent?: (event: { type: string; subject: string; object?: string; location: string; importance: number; payload: Record<string, unknown> }) => Promise<void>,
423	    crimeScenes?: Map<string, import('./world-types').CrimeScene[]>,
424	    evidenceLayer?: EvidenceLayer,
425	    addMoodModifier?: MoodModifierCallback,
426	  ): Promise<GoalActionResult | null> {
427	    const baseResult = {
428	      goalId: goal.id,
429	      goalType: goal.type,
430	      ownerId: goal.ownerId,
431	      ownerName: owner.profile.name,
432	    };
433	
434	    switch (step.action) {
435	      case 'move_to': {
436	        const s = step as MoveStep;
437	        // Already at destination → advance step
438	        if (owner.state.location === s.location) {
439	          goal.currentStep++;
440	          return { ...baseResult, action: 'move_to', description: `${owner.profile.name} arrived at ${s.location}` };
441	        }
442	
443	        // Already in transit → waiting for Master Clock to advance. Skip.
444	        if (owner.state.inTransit) {
445	          return null;
446	        }
447	
448	        // Start transit: compute full path, set duration
449	        const path = findPath(locations, owner.state.location, s.location);
450	        if (!path || path.length === 0) {
451	          goal.currentStep++;
452	          return { ...baseResult, action: 'move_to', description: `${owner.profile.name} cannot reach ${s.location}` };
453	        }
454	
455	        const from = owner.state.location;
456	        // Transit state set by World.startTransit() or inline here
457	        owner.state.inTransit = true;
458	        owner.state.transitTo = s.location;
459	        owner.state.transitPath = path;
460	        // Position-authoritative (Item 2): intent only; arrival is physical, World sets the watchdog baseline.
461	
462	        return {
463	          ...baseResult,
464	          action: 'move_to',
465	          description: `${owner.profile.name} starts walking from ${from} to ${s.location} (${path.length} hops)`,
466	          movement: { agentId: goal.ownerId, agentName: owner.profile.name, from, to: s.location },
467	        };
468	      }
469	
470	      case 'interact': {
471	        const s = step as InteractStep;
472	        const target = agents.get(s.targetId);
473	        if (!target || !target.state.alive) {
474	          goal.currentStep++;
475	          return { ...baseResult, action: 'interact', description: `${owner.profile.name}: target not available` };
476	        }
477	
478	        if (owner.state.location !== target.state.location) {
479	          // Already chasing — wait for transit
480	          if (owner.state.inTransit) return null;
481	
482	          // Chase: pursue target to their CURRENT location
483	          const maxChase = goal.priority >= 7 ? 3 : goal.priority >= 4 ? 2 : 1;
484	          goal.waitTicks = (goal.waitTicks ?? 0) + 1;
485	          if (goal.waitTicks >= maxChase) {
486	            goal.currentStep++;
487	            goal.waitTicks = 0;
488	            return { ...baseResult, action: 'interact', description: `${owner.profile.name}: ${target.profile.name} didn't show up, moving on` };
489	          }
490	
491	          // Start transit to target's current location
492	          const path = findPath(locations, owner.state.location, target.state.location);
493	          if (!path || path.length === 0) {
494	            goal.currentStep++;
495	            return { ...baseResult, action: 'interact', description: `${owner.profile.name}: cannot reach ${target.profile.name}` };
496	          }
497	          const from = owner.state.location;
498	          owner.state.inTransit = true;
499	          owner.state.transitTo = target.state.location;
500	          owner.state.transitPath = path;
501	          console.log(`  [Goal] ${owner.profile.name} pursuing ${target.profile.name} to ${target.state.location}`);
502	          return {
503	            ...baseResult,
504	            action: 'move_to',
505	            description: `${owner.profile.name} pursuing ${target.profile.name}`,
506	            movement: { agentId: goal.ownerId, agentName: owner.profile.name, from, to: target.state.location },
507	          };
508	        }
509	        goal.waitTicks = 0;
510	
511	        const result = await runInteraction(owner, target, s.purpose, s.importance);
512	
513	        // Belief transfer: copy relevant crime beliefs between participants
514	        if (s.beliefTransfer && target.state.beliefs && owner.state.beliefs) {
515	          const direction = s.beliefTransferDirection ?? 'target-to-owner';
516	          const sender = direction === 'owner-to-target' ? owner : target;
517	          const receiver = direction === 'owner-to-target' ? target : owner;
518	          const senderId = direction === 'owner-to-target' ? goal.ownerId : s.targetId;
519	
520	          const { transferred } = transferBeliefs(sender, receiver, senderId, owner.state.currentDay);
521	
522	          // Emit event if step declares an event type (module-registered via emitEventType)
523	          if (onCrimeEvent && s.emitEventType && transferred.length > 0) {
524	            await onCrimeEvent({
525	              type: s.emitEventType,
526	              subject: goal.ownerId,
527	              object: s.targetId,
528	              location: owner.state.location,
529	              importance: s.importance,
530	              payload: {
531	                guardName: owner.profile.name,
532	                witnessName: target.profile.name,
533	                beliefsTransferred: transferred.length,
534	                affectedTargets: [goal.ownerId],
535	              },
536	            });
537	          }
538	        }
539	
540	        // Module-registered post-interaction hooks (e.g., suspect evaluation)
541	        runInteractPostHooks(owner, target, step, agents, crimeScenes);
542	
543	        // Unified initiator memory: beliefs + outcome in one entry (no double observe)
544	        const purposeShort = (s.purpose ?? '').replace(/\[[A-Z_]+[^\]]*\]\s*/g, '');
545	        const pShort = purposeShort.length > 50 ? purposeShort.slice(0, 50) + '...' : purposeShort;
546	        const targetBeliefs3p = target.state.beliefs?.summarizeForMemory(target.profile.name, 1, undefined, target.nameResolver) ?? '';
547	        const outcome = owner.state.lastInteractionOutcome;
548	        const outcomePart = outcome ? ` ${outcome.detail ?? outcome.type}.` : '';
549	        owner.state.lastInteractionOutcome = undefined;
550	        await owner.observe(
551	          `Talked to ${target.profile.name} about ${pShort}.${targetBeliefs3p ? ` ${targetBeliefs3p}.` : ''}${outcomePart}`,
552	          s.importance,
553	        );
554	
555	        goal.currentStep++;
556	
557	        return {
558	          ...baseResult,
559	          action: 'interact',
560	          description: `${owner.profile.name} talked to ${target.profile.name} (${s.purpose})`,
561	          interaction: {
562	            targetId: s.targetId,
563	            targetName: target.profile.name,
564	            ownerLine: result.ownerLine,
565	            targetLine: result.targetLine,
566	            purpose: s.purpose,
567	          },
568	        };
569	      }
570	
571	      case 'interact_present': {
572	        const s = step as InteractPresentStep;
573	        const interacted = (goal.data._interacted as string[]) ?? [];
574	
575	        // Find matching NPCs at current location
576	        const candidates = this.findInteractCandidates(
577	          goal.ownerId, owner, agents, s.filter, interacted,
578	        );
579	
580	        if (candidates.length === 0) {
581	          // No one left to interact with — advance
582	          goal.currentStep++;
583	          goal.data._interacted = [];
584	          return { ...baseResult, action: 'interact_present', description: `${owner.profile.name} finished talking to everyone here` };
585	        }
586	
587	        // Interact with first candidate
588	        const [targetId, target] = candidates[0];
589	        const result = await runInteraction(owner, target, s.purpose, s.importance);
590	
591	        // Belief transfer: reporter's transferable beliefs → target (e.g. witness reports to guard)
592	        if (s.beliefTransfer) {
593	          transferBeliefs(owner, target, goal.ownerId, owner.state.currentDay);
594	        }
595	
596	        interacted.push(targetId);
597	        goal.data._interacted = interacted;
598	
599	        // Check if there are more candidates remaining — if not, advance now
600	        const remaining = this.findInteractCandidates(
601	          goal.ownerId, owner, agents, s.filter, interacted,
602	        );
603	        if (remaining.length === 0) {
604	          goal.currentStep++;
605	          goal.data._interacted = [];
606	        }
607	
608	        return {
609	          ...baseResult,
610	          action: 'interact',
611	          description: `${owner.profile.name} talked to ${target.profile.name} (${s.purpose})`,
612	          interaction: {
613	            targetId,
614	            targetName: target.profile.name,
615	            ownerLine: result.ownerLine,
616	            targetLine: result.targetLine,
617	            purpose: s.purpose,
618	          },
619	        };
620	      }
621	
622	      case 'announce': {
623	        const s = step as AnnounceStep;
624	        // Share message with all NPCs at current location
625	        const recipients: string[] = [];
626	        for (const [id, agent] of agents) {
627	          if (id === goal.ownerId) continue;
628	          if (!agent.state.alive) continue;
629	          if (agent.state.location !== owner.state.location) continue;
630	          await agent.observe(
631	            `${owner.profile.name} announced: "${s.message}"`,
632	            s.importance,
633	          );
634	          recipients.push(id);
635	        }
636	
637	        goal.currentStep++;
638	        return {
639	          ...baseResult,
640	          action: 'announce',
641	          description: `${owner.profile.name} announced: "${s.message}"`,
642	          announcement: { message: s.message, recipients },
643	        };
644	      }
645	
646	      case 'wait': {
647	        const s = step as WaitStep;
648	        const waited = (goal.data._waited as number) ?? 0;
649	        if (waited + 1 >= s.ticks) {
650	          goal.data._waited = 0;
651	          goal.currentStep++;
652	          return { ...baseResult, action: 'wait', description: `${owner.profile.name} finished waiting` };
653	        }
654	        goal.data._waited = waited + 1;
655	        return { ...baseResult, action: 'wait', description: `${owner.profile.name} is waiting...` };
656	      }
657	
658	      // Module-registered step handlers (steal, attack, arrest, sentence, etc.)
659	      default: {
660	        const handler = getStepHandler(step.action);
661	        if (handler) {
662	          return handler({ goal, step, ownerId, owner, agents, locations, runInteraction, onCrimeEvent, crimeScenes, evidenceLayer, goalManager: this,
663	            addMoodModifier: addMoodModifier ?? ((id, m) => console.warn(`[Goals] addMoodModifier not provided for ${id}, modifier ${m.source} lost`)) });
664	        }
665	        return null;
666	      }
667	
668	    }
669	  }
670	
671	  // Step handlers for steal_from, attack_npc, arrest_npc, destroy_evidence, flee,
672	  // examine_scene, sentence_npc moved to modules/crime-justice/step-handlers.ts
673	
674	  private findInteractCandidates(
675	    ownerId: string,
676	    owner: Agent,
677	    agents: Map<string, Agent>,
678	    filter: NpcFilter | undefined,
679	    alreadyInteracted: string[],
680	  ): [string, Agent][] {
681	    const interactedSet = new Set(alreadyInteracted);
682	    const excludeIds = new Set(filter?.excludeIds ?? []);
683	
684	    return Array.from(agents.entries()).filter(([id, agent]) => {
685	      if (id === ownerId) return false;
686	      if (agent.profile.isPlayer) return false; // Player not a valid NPC-NPC interaction target
687	      if (interactedSet.has(id)) return false;
688	      if (excludeIds.has(id)) return false;
689	      if (filter?.onlyAlive !== false && !agent.state.alive) return false;
690	      if (agent.state.location !== owner.state.location) return false;
691	      // role-based filtering removed (INV-14: use capability flags, not role strings)
692	      return true;
693	    });
694	  }
695	}
