1	export type RelationType =
2	  | 'friend'
3	  | 'rival'
4	  | 'family'
5	  | 'acquaintance'
6	  | 'romantic'
7	  | 'mentor'
8	  | 'colleague';
9	
10	export interface Relationship {
11	  targetId: string;
12	  targetName: string;
13	  type: RelationType;
14	  /** -1.0 (hostile) to 1.0 (warm) */
15	  sentiment: number;
16	  /** 0.0 to 1.0: how much they trust this person's word */
17	  trust: number;
18	}
19	
20	/** Default trust by relationship type */
21	export const DEFAULT_TRUST: Record<RelationType, number> = {
22	  family: 0.9,
23	  romantic: 0.85,
24	  friend: 0.8,
25	  mentor: 0.7,
26	  colleague: 0.6,
27	  acquaintance: 0.4,
28	  rival: 0.2,
29	};
30	
31	/** Default sentiment by relationship type */
32	export const DEFAULT_SENTIMENT: Record<RelationType, number> = {
33	  family: 0.7,
34	  romantic: 0.8,
35	  friend: 0.6,
36	  mentor: 0.5,
37	  colleague: 0.3,
38	  acquaintance: 0.1,
39	  rival: -0.3,
40	};
41	
42	export class RelationshipGraph {
43	  private relationships: Map<string, Relationship> = new Map(); // targetId -> Relationship
44	  onChange?: (targetId: string, targetName: string, field: 'trust' | 'sentiment', oldVal: number, newVal: number) => void;
45	
46	  addRelationship(rel: Relationship): void {
47	    this.relationships.set(rel.targetId, rel);
48	  }
49	
50	  getRelationship(targetId: string): Relationship | null {
51	    return this.relationships.get(targetId) ?? null;
52	  }
53	
54	  getAllRelationships(): Relationship[] {
55	    return Array.from(this.relationships.values());
56	  }
57	
58	  adjustSentiment(targetId: string, delta: number): void {
59	    const rel = this.relationships.get(targetId);
60	    if (rel) {
61	      const old = rel.sentiment;
62	      rel.sentiment = Math.max(-1, Math.min(1, rel.sentiment + delta));
63	      if (Math.abs(old - rel.sentiment) > 0.001) this.onChange?.(targetId, rel.targetName, 'sentiment', old, rel.sentiment);
64	    }
65	  }
66	
67	  adjustTrust(targetId: string, delta: number): void {
68	    const rel = this.relationships.get(targetId);
69	    if (rel) {
70	      const old = rel.trust;
71	      rel.trust = Math.max(0, Math.min(1, rel.trust + delta));
72	      if (Math.abs(old - rel.trust) > 0.001) this.onChange?.(targetId, rel.targetName, 'trust', old, rel.trust);
73	    }
74	  }
75	
76	  /** Get trust-weighted confidence for testimony from a specific NPC */
77	  getTestimonyWeight(sourceId: string): number {
78	    const rel = this.relationships.get(sourceId);
79	    return rel?.trust ?? 0.3; // strangers get low trust
80	  }
81	
82	  /** Extra mood penalty when a related NPC dies */
83	  getGriefPenalty(targetId: string): number {
84	    const rel = this.relationships.get(targetId);
85	    if (!rel) return 0;
86	    if (rel.sentiment <= 0) return 0; // no grief for enemies
87	
88	    switch (rel.type) {
89	      case 'family': return -0.4;
90	      case 'romantic': return -0.5;
91	      case 'friend': return -0.3;
92	      case 'mentor': return -0.25;
93	      case 'colleague': return -0.15;
94	      default: return -0.05;
95	    }
96	  }
97	
98	  /** Compact summary for LLM system prompt */
99	  summarizeForPrompt(): string {
100	    const rels = this.getAllRelationships();
101	    if (rels.length === 0) return '';
102	
103	    // Only include meaningful relationships (not bare acquaintances)
104	    // Include relationships with notable sentiment or non-default type
105	    const meaningful = rels.filter((r) => Math.abs(r.sentiment) > 0.15 || r.trust > 0.5);
106	    if (meaningful.length === 0) return '';
107	
108	    return meaningful.map((r) => {
109	      const feeling = r.sentiment > 0.5 ? 'close'
110	        : r.sentiment > 0 ? 'friendly'
111	        : r.sentiment > -0.3 ? 'neutral'
112	        : 'tense';
113	      return `- ${r.targetName}: ${r.type} (${feeling})`;
114	    }).join('\n');
115	  }
116	
117	  /** Serializable snapshot */
118	  toJSON(): Relationship[] {
119	    return this.getAllRelationships();
120	  }
121	
122	  /** Restore from saved snapshot */
123	  static fromJSON(data: Relationship[]): RelationshipGraph {
124	    const graph = new RelationshipGraph();
125	    for (const rel of data) {
126	      graph.addRelationship(rel);
127	    }
128	    return graph;
129	  }
130	}
