62	  private async ensureCollection(): Promise<void> {
63	    const collections = await this.qdrant.getCollections();
64	    const exists = collections.collections.some((c) => c.name === this.collection);
65	
66	    if (exists) {
67	      const needsRecreate = await this.checkEmbeddingDrift();
68	      if (!needsRecreate) return;
69	      await this.qdrant.deleteCollection(this.collection);
70	    }
71	
72	    await this.qdrant.createCollection(this.collection, {
73	      vectors: { size: this.vectorSize, distance: 'Cosine' },
74	    });
75	
76	    // Store metadata point for drift detection
77	    await this.qdrant.upsert(this.collection, {
78	      points: [{
79	        id: META_POINT_ID,
80	        vector: new Array(this.vectorSize).fill(0),
81	        payload: {
82	          _meta: true,
83	          embeddingModel: this.embeddingModel,
84	          vectorSize: this.vectorSize,
85	          createdAt: Date.now(),
86	        },
87	      }],
88	    });
89	  }
90	
91	  /** Returns true if collection must be recreated (model or dimension mismatch) */
92	  private async checkEmbeddingDrift(): Promise<boolean> {
93	    try {
94	      const points = await this.qdrant.retrieve(this.collection, { ids: [META_POINT_ID], with_payload: true });
95	      if (points.length === 0) return true; // no metadata → legacy collection, recreate
96	      const payload = points[0].payload as Record<string, unknown>;
97	      if (payload.embeddingModel !== this.embeddingModel) return true;
98	      if (payload.vectorSize !== this.vectorSize) return true;
99	      return false;
100	    } catch {
101	      return true; // any error → safer to recreate
102	    }
103	  }
