105	  // ─── Embed ──────────────────────────────────────────────────────
106	
107	  private async embed(text: string): Promise<number[]> {
108	    // Идёт через façade → embeddings route → LMStudioProvider (raw fetch внутри, Matryoshka сохраняется)
109	    const vec = await embed(text);
110	    if (!vec) {
111	      throw new Error(`[Memory] embed() returned null — LM Studio down? Check provider logs.`);
112	    }
113	    return vec;
114	  }
115	
116	  // ─── Store: dual write ──────────────────────────────────────────
117	
118	  async store(text: string, importance: number, gameDay: number, isProtected?: boolean, playerId?: string): Promise<void> {
119	    const vector = await this.embed(text);
120	    const entry: MemoryEntry = {
121	      id: crypto.randomUUID(),
122	      text,
123	      importance,
124	      gameDay,
125	      timestamp: Date.now(),
126	      vector,
127	      embeddingModel: this.embeddingModel,
128	      protected: isProtected || undefined,
129	      playerId: playerId ?? WORLD_MEMORY_OWNER,
130	    };
131	
132	    this._memoryLog.push(entry);
133	    this.evictIfNeeded();
134	
135	    // Search index (best-effort)
136	    if (this._qdrantAvailable) {
137	      try {
138	        await this.qdrant.upsert(this.collection, {
139	          points: [{ id: entry.id, vector: entry.vector, payload: this.entryPayload(entry) }],
140	        });
141	      } catch (e) {
142	        console.warn(`[Memory] Qdrant upsert failed, search degraded: ${e}`);
143	        this._qdrantAvailable = false;
144	      }
145	    }
146	  }
147	
148	  // ─── Recall: composite scoring, 3-level fallback ───────────────
149	
150	  async recall(query: string, currentDay: number, topK: number = 5, playerId?: string): Promise<ScoredMemory[]> {
151	    let results: ScoredMemory[];
152	
153	    if (this._qdrantAvailable) {
154	      try {
155	        const vector = await this.embed(query);
156	        const raw = await this.qdrant.search(this.collection, {
157	          vector, limit: topK * 3, with_payload: true,
158	        });
159	        results = raw
160	          .filter((r) => r.id !== META_POINT_ID)
161	          .map((r) => {
162	            const p = r.payload as Record<string, unknown>;
163	            const entryPlayerId = (p.playerId as string) ?? WORLD_MEMORY_OWNER;
164	            return { ...this.payloadToScore(p, currentDay), relevance: r.score, entryPlayerId };
165	          })
166	          .filter((m) => this.matchesPlayerScope(m.entryPlayerId, playerId))
167	          .map(({ entryPlayerId: _, ...rest }) => rest);
168	      } catch (e) {
169	        console.warn(`[Memory] Qdrant search failed, falling back to cosine: ${e}`);
170	        this._qdrantAvailable = false;
171	        results = await this.fallbackRecall(query, currentDay, topK * 3, playerId);
172	      }
173	    } else {
174	      results = await this.fallbackRecall(query, currentDay, topK * 3, playerId);
175	    }
176	
177	    // Composite scoring: relevance × 0.4 + decayedImportance × 0.4 + freshness × 0.2
178	    for (const m of results) {
179	      m.compositeScore = m.relevance * 0.4 + m.decayedImportance * 0.4 + m.freshness * 0.2;
180	    }
181	    results.sort((a, b) => b.compositeScore - a.compositeScore);
182	    return results.slice(0, topK);
183	  }
184	
185	  /** Fallback: brute-force cosine on _memoryLog */
186	  private async fallbackRecall(query: string, currentDay: number, limit: number, playerId?: string): Promise<ScoredMemory[]> {
187	    let qVec: number[];
188	    try {
189	      qVec = await this.embed(query);
190	    } catch {
191	      // LM Studio also down — keyword fallback
192	      return this.keywordRecall(query, currentDay, limit, playerId);
193	    }
194	    const filtered = this.filterByPlayer(playerId);
195	    return filtered.map((e) => ({
196	      ...this.baseScore(e, currentDay),
197	      relevance: cosineSimilarity(qVec, e.vector),
198	    })).sort((a, b) => b.relevance - a.relevance).slice(0, limit);
199	  }
200	
201	  /** Last resort: keyword match when both Qdrant and LM Studio down */
202	  private keywordRecall(query: string, currentDay: number, limit: number, playerId?: string): ScoredMemory[] {
203	    const words = query.toLowerCase().split(/\s+/).filter((w) => w.length > 3);
204	    const filtered = this.filterByPlayer(playerId);
205	    return filtered
206	      .map((e) => {
207	        const text = e.text.toLowerCase();
208	        const hits = words.filter((w) => text.includes(w)).length;
209	        return { ...this.baseScore(e, currentDay), relevance: hits / Math.max(words.length, 1) };
210	      })
211	      .filter((m) => m.relevance > 0)
212	      .sort((a, b) => b.relevance - a.relevance)
213	      .slice(0, limit);
214	  }
215	
216	  // ─── getAllMemories: sync, from _memoryLog ──────────────────────
217	
218	  getAllMemories(currentDay: number, playerId?: string): ScoredMemory[] {
219	    const filtered = this.filterByPlayer(playerId);
220	    return filtered.map((e) => this.baseScore(e, currentDay));
221	  }
