223	  // ─── Persistence ────────────────────────────────────────────────
224	
225	  toJSON(): MemoryEntry[] {
226	    return this._memoryLog;
227	  }
228	
229	  async loadState(entries: MemoryEntry[]): Promise<void> {
230	    // Migration: add playerId if missing (v1 → v2)
231	    for (const e of entries) {
232	      if (!e.playerId) e.playerId = WORLD_MEMORY_OWNER;
233	    }
234	    this._memoryLog = entries;
235	
236	    // Re-embed if model changed
237	    const needsReembed = entries.length > 0 && entries.some((e) => e.embeddingModel !== this.embeddingModel);
238	    if (needsReembed) {
239	      console.warn(`[Memory] Embedding model changed, re-embedding ${entries.length} memories...`);
240	      let done = 0;
241	      for (const e of entries) {
242	        if (e.embeddingModel !== this.embeddingModel) {
243	          e.vector = await this.embed(e.text);
244	          e.embeddingModel = this.embeddingModel;
245	        }
246	        if (++done % 50 === 0) console.log(`[Memory] Re-embedded ${done}/${entries.length}...`);
247	      }
248	    }
249	
250	    // Batch upsert to Qdrant (rebuild search index from _memoryLog)
251	    if (entries.length > 0 && this._qdrantAvailable) {
252	      try {
253	        await this.qdrant.upsert(this.collection, {
254	          points: entries.map((e) => ({ id: e.id, vector: e.vector, payload: this.entryPayload(e) })),
255	        });
256	      } catch (e) {
257	        console.warn(`[Memory] Qdrant batch upsert failed: ${e}`);
258	        this._qdrantAvailable = false;
259	      }
260	    }
261	  }
262	
263	  // ─── Eviction: decayedImportance, protected memories immune ─────
264	
265	  private evictIfNeeded(): void {
266	    if (this._memoryLog.length <= this._maxCapacity) return;
267	
268	    // Single-pass: find currentDay and worst entry simultaneously
269	    let currentDay = 0;
270	    for (const e of this._memoryLog) {
271	      if (e.gameDay > currentDay) currentDay = e.gameDay;
272	    }
273	    let worstIdx = -1;
274	    let worstScore = Infinity;
275	    for (let i = 0; i < this._memoryLog.length; i++) {
276	      const e = this._memoryLog[i];
277	      if (e.protected) continue; // protected memories NEVER evicted
278	      const score = decayedImportance(e.importance, currentDay - e.gameDay);
279	      if (score < worstScore) { worstScore = score; worstIdx = i; }
280	    }
281	
282	    if (worstIdx === -1) return; // all protected — over capacity but can't evict
283	    const victim = this._memoryLog[worstIdx];
284	    this._memoryLog.splice(worstIdx, 1);
285	    if (this._qdrantAvailable) {
286	      this.qdrant.delete(this.collection, { points: [victim.id] }).catch(() => {});
287	    }
288	  }
289	
290	  // ─── Player scope filtering (multiplayer-ready) ────────────────
291	
292	  private filterByPlayer(playerId?: string): MemoryEntry[] {
293	    if (!playerId) return this._memoryLog.filter((e) => e.playerId === WORLD_MEMORY_OWNER);
294	    return this._memoryLog.filter((e) => e.playerId === playerId || e.playerId === WORLD_MEMORY_OWNER);
295	  }
296	
297	  private matchesPlayerScope(entryPlayerId: string, queryPlayerId?: string): boolean {
298	    if (!queryPlayerId) return entryPlayerId === WORLD_MEMORY_OWNER;
299	    return entryPlayerId === queryPlayerId || entryPlayerId === WORLD_MEMORY_OWNER;
300	  }
301	
302	  // ─── Helpers ────────────────────────────────────────────────────
303	
304	  private entryPayload(e: MemoryEntry): Record<string, unknown> {
305	    return { text: e.text, importance: e.importance, gameDay: e.gameDay, timestamp: e.timestamp, playerId: e.playerId ?? WORLD_MEMORY_OWNER };
306	  }
307	
308	  private baseScore(e: MemoryEntry, currentDay: number): ScoredMemory {
309	    const daysPassed = currentDay - e.gameDay;
310	    return {
311	      id: e.id, text: e.text, importance: e.importance,
312	      gameDay: e.gameDay, timestamp: e.timestamp,
313	      relevance: 0,
314	      decayedImportance: decayedImportance(e.importance, daysPassed),
315	      freshness: freshness(daysPassed),
316	      compositeScore: 0,
317	    };
318	  }
319	
320	  private payloadToScore(p: Record<string, unknown>, currentDay: number): ScoredMemory {
321	    const imp = p.importance as number;
322	    const day = p.gameDay as number;
323	    const daysPassed = currentDay - day;
324	    return {
325	      id: String(p.id ?? ''),
326	      text: p.text as string,
327	      importance: imp,
328	      gameDay: day,
329	      timestamp: p.timestamp as number,
330	      relevance: 0,
331	      decayedImportance: decayedImportance(imp, daysPassed),
332	      freshness: freshness(daysPassed),
333	      compositeScore: 0,
334	    };
335	  }
336	}
337	
338	function cosineSimilarity(a: number[], b: number[]): number {
339	  let dot = 0, magA = 0, magB = 0;
340	  for (let i = 0; i < a.length; i++) {
341	    dot += a[i] * b[i]; magA += a[i] * a[i]; magB += b[i] * b[i];
342	  }
343	  return dot / (Math.sqrt(magA) * Math.sqrt(magB) + 1e-8);
344	}
