13	/** Callback for adding mood modifiers from module code (SPEC-mood-modifiers) */
14	export type MoodModifierCallback = (npcId: string, mod: {
15	  source: string; category: string; magnitude: number;
16	  remaining: number; duration: number; decay: 'exponential' | 'linear' | 'none';
17	}) => void;
