244	// ─── Universal Role-Based Finder (proximity-aware, enriches with crime beliefs) ───
245	
246	export function findByRole(role: string, npcId: string, agent: Agent, ctx: AffordanceContext): AffordanceTarget | null {
247	  type Candidate = { id: string; name: string; location: string; distance: number };
248	  const candidates: Candidate[] = [];
249	
250	  for (const [otherId, other] of ctx.agents) {
251	    if (otherId === npcId || !other.state.alive) continue;
252	    if (isStatusAbsent(other.state.status)) continue;
253	    if (other.profile.role === role) {
254	      let distance: number;
255	      if (other.state.location === agent.state.location) {
256	        distance = 0;
257	      } else {
258	        const loc = ctx.locations.get(agent.state.location);
259	        distance = loc?.connections.includes(other.state.location) ? 1 : 2;
260	      }
261	      candidates.push({ id: otherId, name: other.profile.name, location: other.state.location, distance });
262	    }
263	  }
264	
265	  if (candidates.length === 0) return null;
266	  candidates.sort((a, b) => a.distance - b.distance);
267	  const best = candidates[0];
268	
269	  // Enrich with crime details from NPC's own beliefs (universal — harmless if no beliefs)
270	  const extra: Record<string, string> = {};
271	  const beliefs = agent.state.beliefs?.getAllBeliefs() ?? [];
272	  const crimeBelief = beliefs.find(
273	    (b: Belief) => isTransferable(b.eventType) && b.confidence >= 0.3,
274	  );
275	  if (crimeBelief) {
276	    if (crimeBelief.subject) { extra.perpetratorName = crimeBelief.subject; }
277	    if (crimeBelief.object) extra.affectedName = crimeBelief.object;
278	    if (crimeBelief.location) extra.crimeLocation = crimeBelief.location;
279	    extra.crimeType = getEventLabelSafe(crimeBelief.eventType);
280	  }
281	
282	  return { targetId: best.id, targetName: best.name, targetLocation: best.location, extra };
283	}
