287	/** Generic iteration over all REQUIREMENT_CHECKERS registry entries */
288	function checkRegistryRequirements(req: AffordanceRequirement, agent: Agent, ctx: AffordanceContext): boolean {
289	  const reqRecord = req as Record<string, unknown>;
290	  for (const [key, checker] of REQUIREMENT_CHECKERS) {
291	    if (!reqRecord[key]) continue;
292	    // Pass affordance-level params (e.g. beliefConfidence for hasCrimeBelief)
293	    const params: Record<string, unknown> = {};
294	    if (req.beliefConfidence !== undefined) params.minConfidence = req.beliefConfidence;
295	    if (!checker(agent, ctx, params)) return false;
296	  }
297	  return true;
298	}
