300	/** Post-target checks: noGuardNearby, maxWitnesses, sentimentBelow */
301	function checkPostTargetRequirements(req: AffordanceRequirement, npcId: string, target: AffordanceTarget, ctx: AffordanceContext): boolean {
302	  if (req.noGuardNearby) {
303	    for (const [, other] of ctx.agents) {
304	      if (!other.state.alive) continue;
305	      if (other.profile.detersCrime && other.state.location === target.targetLocation) return false;
306	    }
307	  }
308	  if (req.maxWitnesses !== undefined) {
309	    let witnessCount = 0;
310	    for (const [otherId, other] of ctx.agents) {
311	      if (otherId === npcId || otherId === target.targetId) continue;
312	      if (!other.state.alive) continue;
313	      if (other.state.location === target.targetLocation) witnessCount++;
314	    }
315	    if (witnessCount > req.maxWitnesses) return false;
316	  }
317	  if (req.sentimentBelow !== undefined) {
318	    const rel = ctx.agents.get(npcId)?.state.relationships?.getRelationship(target.targetId);
319	    if (!rel || rel.sentiment >= req.sentimentBelow) return false;
320	  }
321	  return true;
322	}
